import{_ as e,o as s,c as a,a4 as t}from"./chunks/framework.DzJZdBQK.js";const b=JSON.parse('{"title":"Hbase Indexer - 入门","description":"","frontmatter":{"date":"2018-12-05T12:31:00","title":"Hbase Indexer - 入门","categories":["hbase","hbase indexer"],"tags":["hbase","hbase indexer"]},"headers":[{"level":2,"title":"构建（Building the binary distribution）","slug":"构建-building-the-binary-distribution","link":"#构建-building-the-binary-distribution","children":[]},{"level":2,"title":"测试（Testing）","slug":"测试-testing","link":"#测试-testing","children":[]}],"relativePath":"posts/bigdata/hbase-indexer/getting-start.md","filePath":"posts/bigdata/hbase-indexer/getting-start.md"}'),n={name:"posts/bigdata/hbase-indexer/getting-start.md"};function l(r,i,d,o,h,p){return s(),a("div",null,[...i[0]||(i[0]=[t(`<h2 id="构建-building-the-binary-distribution" tabindex="-1">构建（Building the binary distribution） <a class="header-anchor" href="#构建-building-the-binary-distribution" aria-label="Permalink to &quot;构建（Building the binary distribution）&quot;">​</a></h2><p>Use the following command to build the binary distribution (.tar.gz &amp; rpm):</p><p>使用如下命令构建生成二进制发布包（.tar.gz &amp; rpm）:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mvn -DskipTests -Pdist install</span></span></code></pre></div><h2 id="测试-testing" tabindex="-1">测试（Testing） <a class="header-anchor" href="#测试-testing" aria-label="Permalink to &quot;测试（Testing）&quot;">​</a></h2><p>These steps assume a running HBase 0.94.x installation (preferably CDH 4.2), as well as a running Solr installation. For this example, the configured Solr schema will need to have a multi-valued field called &quot;data&quot;, as well as a unique key field called &quot;id&quot;.</p><p>以下这此步骤假定已经安装了Hbase 0.94.x(最好是CDH 4.2)和Solr。在这个例子中，Solr的映射，需要配置多值字段“data”和唯一键字段“id”。</p><ol><li><p>Enable replication and other settings that are outlined in the <a href="https://github.com/NGDATA/hbase-indexer/blob/master/hbase-sep/hbase-sep-demo/README.md" target="_blank" rel="noreferrer">hbase-sep demo instructions</a></p></li><li><p>按<a href="https://github.com/NGDATA/hbase-indexer/blob/master/hbase-sep/hbase-sep-demo/README.md" target="_blank" rel="noreferrer">hbase-sep demo instructions</a>的配置复制集和其他设置。</p></li><li><p>Unzip the binary distribution (instructions for creating the binary distribution are listed above).</p></li><li><p>解压发布包（生成发布包的方式已经在上文列出）。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> $ tar zxvf hbase_indexer.tar.gz</span></span></code></pre></div><ol start="3"><li>Copy the hbase-sep jar files from the lib directory of the binary distribution into the lib directory of HBase.</li><li>将发布包下的lib目录的hbase-sep jar文件拷贝到Hbase的lib目录。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> $ cd hbase_indexer</span></span>
<span class="line"><span> $ sudo cp lib/hbase-sep-* /usr/lib/hbase/lib</span></span></code></pre></div><ol start="4"><li>Create a table in HBase that has replication enabled. For this example, we&#39;ll create a table called &quot;record&quot; with a single column family called &#39;data&#39;.</li><li>创建一个开启复制集功能的表。这个例子中，我们会创建“record”表，有一个列簇“data”。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> hbase&gt; create &#39;record&#39;, {NAME =&gt; &#39;data&#39;, REPLICATION_SCOPE =&gt; 1}</span></span></code></pre></div><ol start="5"><li>Start the hbase-indexer server</li><li>启动hbase-indexer服务</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> $ ./bin/hbase-indexer server</span></span></code></pre></div><ol start="6"><li>Create an indexer definition. For this example, we&#39;ll just index anything in the data column family into the &quot;data&quot; field in Solr. Save the below contents in a file called &#39;sample.xml&#39;.</li><li>创建索引器定义。在这个例子中，我们只是把data列簇中所有内容都放到Solr的“data”字段中进行索引。将以下内容保存为&quot;sample.xml&quot;。</li></ol><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;?</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xml</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">?&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">indexer</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> table</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;record&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">field</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data:*&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">indexer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ol start="7"><li>Add the indexer definition to the indexer server. The following command assumes that the Solr ZooKeeper is running on the current host, and the name of the collection to be used for indexing is &quot;core0&quot;.</li><li>把索引定义添加到inderxer服务中。下面的命令假设Solr ZooKeeper运行在当前的主机中，并且用于索引的集合名为“core0”。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> $ ./bin/hbase-indexer add-indexer  -n sampleindex -c sample.xml --cp solr.collection=core0</span></span></code></pre></div><ol start="8"><li>Add some data to the record table in HBase. The data added to the data column family in the record table should show up in the Solr index.</li><li>向Hbase的recode表添加一些数据。添加到record表中的数据应该会出现在Solr的索引中。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> hbase&gt; put &#39;record&#39;, &#39;row1&#39;, &#39;data:value&#39;, &#39;Test of HBase Indexer&#39;</span></span></code></pre></div>`,21)])])}const g=e(n,[["render",l]]);export{b as __pageData,g as default};
